1	#!/usr/bin/env node
2	/**
3	 * test7.mjs — Node.js port of /workspace/dataset/test7.py
4	 *
5	 * Original:
6	 *
7	 *     parser = argparse.ArgumentParser()
8	 *     parser.add_argument('--a', type=str, required=True)
9	 *     parser.add_argument('--b', type=str, required=True)
10	 *     args = parser.parse_args()
11	 *
12	 *     data = [args.a, args.b]
13	 *     result1 = canonicaljson.encode_canonical_json(data)
14	 *     result2 = canonicaljson.encode_canonical_json(sorted(data))
15	 *     print(result1)
16	 *     print(result2)
17	 *
18	 * `print()` of a `bytes` object emits its repr, so both lines come out as
19	 * `b'...'` with Python's byte-escaping rules applied on top of the JSON text.
20	 */
21	
22	import { ArgumentParser } from './lib/argparse.mjs';
23	import { encodeCanonicalJson } from './lib/canonicaljson.mjs';
24	import { pySorted } from './lib/pysort.mjs';
25	import { scriptArgs } from './lib/pyargv.mjs';
26	import { pyPrint } from './lib/pyio.mjs';
27	import { runMain } from './lib/pyruntime.mjs';
28	
29	export function main() {
30	  const parser = new ArgumentParser();
31	  parser.addArgument('--a', { type: 'str', required: true });
32	  parser.addArgument('--b', { type: 'str', required: true });
33	  const args = parser.parseArgs(scriptArgs());
34	
35	  const data = [args.a, args.b];
36	  const result1 = encodeCanonicalJson(data); // Encode list as canonical JSON
37	  const result2 = encodeCanonicalJson(pySorted(data)); // Encode sorted list as canonical JSON
38	  pyPrint(result1);
39	  pyPrint(result2);
40	}
41	
42	// Frame list for the one unhandled exception this program can raise: a lone
43	// surrogate in either argument makes the UTF-8 encode inside
44	// encode_canonical_json fail, which CPython reports from test7.py line 12.
45	runMain(main, {
46	  script: 'test7',
47	  traceback: [
48	    { file: 'test7.py', line: 18, name: '<module>' },
49	    { file: 'test7.py', line: 12, name: 'main' },
50	    { file: 'canonicaljson/__init__.py', line: 85, name: 'encode_canonical_json' },
51	  ],
52	});
53

1	/**
2	 * index.mjs — single entry point for the whole port.
3	 *
4	 * The modules underneath split along the same seams as the Python packages they
5	 * stand in for:
6	 *
7	 *   pyerrors.mjs     exception classes and their `__str__` renderings
8	 *   pyunicode.mjs    str <-> UTF-8 bytes (strict encode, surrogateescape decode)
9	 *   pybytes.mjs      the `bytes` type and `repr(bytes)`
10	 *   pynumber.mjs     `int.__repr__` / `float.__repr__`
11	 *   pysort.mjs       code point ordering for `sorted()` and `sort_keys=True`
12	 *   textwrap.mjs     the `textwrap.wrap` subset argparse's help needs
13	 *   jsonencoder.mjs  `json.JSONEncoder` serialisation (bespoke, no host JSON)
14	 *   canonicaljson.mjs the `canonicaljson` package surface
15	 *   argparse.mjs     `argparse.ArgumentParser`
16	 *   pyargv.mjs       `sys.argv` recovery with byte fidelity
17	 *   pyio.mjs         `print()` and synchronous stream writes
18	 *   pyruntime.mjs    top-level exit and traceback behaviour
19	 */
20	
21	export { PyError, SystemExit, PyValueError, PyTypeError, UnicodeEncodeError } from './pyerrors.mjs';
22	export {
23	  isSurrogate,
24	  pyLen,
25	  codePoints,
26	  encodeUtf8Strict,
27	  decodeSurrogateEscape,
28	} from './pyunicode.mjs';
29	export { PyBytes, bytesRepr } from './pybytes.mjs';
30	export { PyFloat, pyIntRepr, pyFloatRepr, jsonNumberRepr } from './pynumber.mjs';
31	export { compareCodePoints, pySorted } from './pysort.mjs';
32	export { collapseWhitespace, wrapText, fillText } from './textwrap.mjs';
33	export { encodeJsonString, encodeJsonValue } from './jsonencoder.mjs';
34	export { encodeCanonicalJson, encodePrettyPrintedJson } from './canonicaljson.mjs';
35	export { ArgumentParser, Namespace } from './argparse.mjs';
36	export { scriptArgs } from './pyargv.mjs';
37	export { writeStdout, writeStderr, pyRepr, pyPrint } from './pyio.mjs';
38	export { runMain, formatTraceback } from './pyruntime.mjs';
39

1	/**
2	 * canonicaljson.mjs — reimplementation of the `canonicaljson` package's public
3	 * surface, derived from the reference executable's observable behaviour.
4	 *
5	 * `encode_canonical_json(obj)` produces `bytes`:
6	 *
7	 *   * keys sorted, no insignificant whitespace (`separators=(',', ':')`)
8	 *   * `ensure_ascii=False`, so non-ASCII text is carried as raw UTF-8 rather
9	 *     than `\uXXXX` escapes — this is why the reference prints
10	 *     b'["\xe6\x97\xa5\xe6\x9c\xac\xe8\xaa\x9e","ascii"]' for Japanese input
11	 *   * the JSON *text* is built first and encoded to UTF-8 last, so a lone
12	 *     surrogate anywhere in the input raises `UnicodeEncodeError` with a
13	 *     position measured against the finished JSON text
14	 */
15	
16	import { PyBytes } from './pybytes.mjs';
17	import { encodeJsonValue, encodeJsonString } from './jsonencoder.mjs';
18	import { encodeUtf8Strict } from './pyunicode.mjs';
19	import { compareCodePoints } from './pysort.mjs';
20	
21	/** `canonicaljson.encode_canonical_json(obj) -> bytes` */
22	export function encodeCanonicalJson(obj) {
23	  return new PyBytes(encodeUtf8Strict(encodeJsonValue(obj)));
24	}
25	
26	/**
27	 * `canonicaljson.encode_pretty_printed_json(obj) -> bytes`
28	 *
29	 * Provided for parity with the package's surface; `test7.py` does not use it.
30	 * The pretty encoder keeps `sort_keys=True` and `ensure_ascii=False` but adds
31	 * `indent=4`, which also switches the separators to `(',', ': ')`.
32	 */
33	export function encodePrettyPrintedJson(obj) {
34	  return new PyBytes(encodeUtf8Strict(prettyEncode(obj, 0)));
35	}
36	
37	function isMapping(value) {
38	  return value !== null && typeof value === 'object' && !Array.isArray(value);
39	}
40	
41	function prettyEncode(value, depth) {
42	  const pad = ' '.repeat(4 * (depth + 1));
43	  const closePad = ' '.repeat(4 * depth);
44	
45	  if (Array.isArray(value)) {
46	    if (value.length === 0) return '[]';
47	    const items = value.map((item) => pad + prettyEncode(item, depth + 1));
48	    return '[\n' + items.join(',\n') + '\n' + closePad + ']';
49	  }
50	
51	  if (isMapping(value) && !(value instanceof PyBytes)) {
52	    const entries = value instanceof Map ? Array.from(value.entries()) : Object.entries(value);
53	    if (entries.length === 0) return '{}';
54	    const items = entries
55	      .map(([key, item]) => [String(key), item])
56	      .sort((left, right) => compareCodePoints(left[0], right[0]))
57	      .map(([key, item]) => `${pad}${encodeJsonString(key)}: ${prettyEncode(item, depth + 1)}`);
58	    return '{\n' + items.join(',\n') + '\n' + closePad + '}';
59	  }
60	
61	  // Scalars share the canonical encoder's number formatting and escape table.
62	  return encodeJsonValue(value);
63	}
64	
65	export { PyBytes };
66

1	/**
2	 * jsonencoder.mjs — a hand-written port of `json.JSONEncoder`'s serialisation,
3	 * configured the way canonicaljson configures it:
4	 *
5	 *     json.JSONEncoder(
6	 *         ensure_ascii=False,      # non-ASCII stays raw, no \uXXXX escapes
7	 *         allow_nan=False,         # NaN/Infinity raise ValueError
8	 *         separators=(',', ':'),   # no whitespace anywhere
9	 *         sort_keys=True,          # object keys in code point order
10	 *     )
11	 *
12	 * The result is a Python `str`; the UTF-8 encoding step happens afterwards in
13	 * `canonicaljson.mjs`. Keeping the two stages separate is what makes the
14	 * surrogate error positions line up with the reference implementation, because
15	 * CPython reports them as offsets into the finished JSON *text*.
16	 *
17	 * Everything here is bespoke: no host JSON serialiser is consulted, since the
18	 * escape table, key ordering and number formatting all have to follow CPython
19	 * rather than ECMAScript.
20	 */
21	
22	import { PyTypeError, PyValueError } from './pyerrors.mjs';
23	import { compareCodePoints } from './pysort.mjs';
24	import { PyFloat, jsonNumberRepr } from './pynumber.mjs';
25	
26	/**
27	 * `json.encoder.ESCAPE_DCT`, restricted to the entries that fire when
28	 * `ensure_ascii=False`. Note `/` is *not* escaped and neither is U+007F.
29	 */
30	const ESCAPE_TABLE = new Map([
31	  [0x5c, '\\\\'], // backslash
32	  [0x22, '\\"'], // double quote
33	  [0x08, '\\b'],
34	  [0x0c, '\\f'],
35	  [0x0a, '\\n'],
36	  [0x0d, '\\r'],
37	  [0x09, '\\t'],
38	]);
39	
40	/**
41	 * `py_encode_basestring` — quote a string, escaping only what JSON requires.
42	 *
43	 * Iterating UTF-16 units rather than code points is deliberate and safe: every
44	 * escaped character is ASCII, so astral characters and lone surrogates are
45	 * copied through untouched either way, and surrogates must survive to this
46	 * point so that the later UTF-8 encode can reject them.
47	 */
48	export function encodeJsonString(value) {
49	  let out = '"';
50	  for (let i = 0; i < value.length; i += 1) {
51	    const unit = value.charCodeAt(i);
52	    const escape = ESCAPE_TABLE.get(unit);
53	    if (escape !== undefined) {
54	      out += escape;
55	    } else if (unit < 0x20) {
56	      out += '\\u' + unit.toString(16).padStart(4, '0');
57	    } else {
58	      out += value[i];
59	    }
60	  }
61	  return out + '"';
62	}
63	
64	/**
65	 * Normalises a mapping into `[key, value]` pairs. `Map` is supported so callers
66	 * can use non-string keys the way a Python `dict` would, and plain objects are
67	 * treated as string-keyed dicts over their own enumerable properties.
68	 */
69	function mappingEntries(value) {
70	  if (value instanceof Map) return Array.from(value.entries());
71	  return Object.keys(value).map((key) => [key, value[key]]);
72	}
73	
74	/**
75	 * `json` coerces non-string keys before writing them: `True`/`False`/`None`
76	 * become their Python literals, numbers use their repr, and anything else is a
77	 * TypeError.
78	 */
79	function coerceKey(key) {
80	  if (typeof key === 'string') return key;
81	  if (key === true) return 'true';
82	  if (key === false) return 'false';
83	  if (key === null) return 'null';
84	  if (typeof key === 'number' || typeof key === 'bigint' || key instanceof PyFloat) {
85	    return jsonNumberRepr(key);
86	  }
87	  throw new PyTypeError(`keys must be str, int, float, bool or None, not ${typeName(key)}`);
88	}
89	
90	function typeName(value) {
91	  if (value === null) return 'NoneType';
92	  if (Array.isArray(value)) return 'list';
93	  if (value instanceof Map) return 'dict';
94	  if (value instanceof PyFloat) return 'float';
95	  switch (typeof value) {
96	    case 'string':
97	      return 'str';
98	    case 'boolean':
99	      return 'bool';
100	    case 'bigint':
101	      return 'int';
102	    case 'number':
103	      return Number.isInteger(value) ? 'int' : 'float';
104	    case 'undefined':
105	      return 'undefined';
106	    default:
107	      return 'object';
108	  }
109	}
110	
111	/**
112	 * Serialise `value` to a canonical JSON *string*.
113	 *
114	 * `seen` reproduces `json`'s circular-reference guard, which raises
115	 * `ValueError: Circular reference detected`.
116	 */
117	export function encodeJsonValue(value, seen = new Set()) {
118	  if (value === null || value === undefined) return 'null';
119	  if (value === true) return 'true';
120	  if (value === false) return 'false';
121	  if (typeof value === 'string') return encodeJsonString(value);
122	  if (typeof value === 'number' || typeof value === 'bigint' || value instanceof PyFloat) {
123	    return jsonNumberRepr(value);
124	  }
125	
126	  if (Array.isArray(value)) {
127	    if (seen.has(value)) throw new PyValueError('Circular reference detected');
128	    seen.add(value);
129	    const parts = value.map((item) => encodeJsonValue(item, seen));
130	    seen.delete(value);
131	    return '[' + parts.join(',') + ']';
132	  }
133	
134	  if (typeof value === 'object') {
135	    if (seen.has(value)) throw new PyValueError('Circular reference detected');
136	    seen.add(value);
137	    // sort_keys=True sorts the coerced keys in code point order.
138	    const parts = mappingEntries(value)
139	      .map(([key, item]) => [coerceKey(key), item])
140	      .sort((left, right) => compareCodePoints(left[0], right[0]))
141	      .map(([key, item]) => encodeJsonString(key) + ':' + encodeJsonValue(item, seen));
142	    seen.delete(value);
143	    return '{' + parts.join(',') + '}';
144	  }
145	
146	  throw new PyTypeError(`Object of type ${typeName(value)} is not JSON serializable`);
147	}
148

1	/**
2	 * pyunicode.mjs — the `str` <-> `bytes` boundary, with CPython's exact semantics.
3	 *
4	 * Two conversions matter for this program:
5	 *
6	 *   1. `os.fsdecode` / `sys.argv` decoding: UTF-8 with `errors='surrogateescape'`.
7	 *      Every byte CPython's UTF-8 decoder rejects becomes U+DC00+byte, i.e. a
8	 *      lone *low* surrogate in U+DC80..U+DCFF.
9	 *
10	 *   2. `str.encode('utf-8')` with `errors='strict'`, which is what canonicaljson
11	 *      performs last. Any surrogate code point raises `UnicodeEncodeError`, and
12	 *      CPython groups *consecutive* surrogates into one error range.
13	 *
14	 * Representation note: a Python `str` is modelled as a JS string. JS strings are
15	 * UTF-16, so in principle a high surrogate followed by a low surrogate would be
16	 * read back as one astral code point rather than two Python surrogates. That
17	 * ambiguity cannot arise here: `surrogateescape` only ever emits *low*
18	 * surrogates (U+DC80..U+DCFF), and a well-formed pair requires a *high*
19	 * surrogate first, so escaped bytes never coalesce.
20	 */
21	
22	import { UnicodeEncodeError } from './pyerrors.mjs';
23	
24	const SURROGATE_LOW = 0xd800;
25	const SURROGATE_HIGH = 0xdfff;
26	
27	export function isSurrogate(cp) {
28	  return cp >= SURROGATE_LOW && cp <= SURROGATE_HIGH;
29	}
30	
31	/** `len(s)` — Python counts code points, JS's `.length` counts UTF-16 units. */
32	export function pyLen(str) {
33	  let n = 0;
34	  for (const _ of str) n += 1;
35	  return n;
36	}
37	
38	/** `[ord(c) for c in s]` */
39	export function codePoints(str) {
40	  const out = [];
41	  for (const ch of str) out.push(ch.codePointAt(0));
42	  return out;
43	}
44	
45	/**
46	 * How many bytes a code point occupies in UTF-8, mirroring the table CPython
47	 * uses. Surrogates are handled by the caller (they are an error).
48	 */
49	function utf8Width(cp) {
50	  if (cp < 0x80) return 1;
51	  if (cp < 0x800) return 2;
52	  if (cp < 0x10000) return 3;
53	  return 4;
54	}
55	
56	/**
57	 * `s.encode('utf-8')` with `errors='strict'`.
58	 *
59	 * Returns a `Uint8Array`. Raises `UnicodeEncodeError` on the first run of
60	 * surrogate code points, reporting the run's start/end as code point indices —
61	 * exactly what CPython's `_PyUnicode_EncodeUTF8` does when it walks forward
62	 * while `Py_UNICODE_IS_SURROGATE` holds.
63	 */
64	export function encodeUtf8Strict(str) {
65	  const out = [];
66	  let cpIndex = 0;
67	  let u = 0;
68	
69	  while (u < str.length) {
70	    const cp = str.codePointAt(u);
71	
72	    if (isSurrogate(cp)) {
73	      // Collect the maximal run of consecutive surrogates for the error range.
74	      let end = cpIndex + 1;
75	      let scan = u + 1; // a lone surrogate always occupies one UTF-16 unit
76	      while (scan < str.length && isSurrogate(str.codePointAt(scan))) {
77	        end += 1;
78	        scan += 1;
79	      }
80	      throw new UnicodeEncodeError('utf-8', str, cpIndex, end, 'surrogates not allowed');
81	    }
82	
83	    if (cp < 0x80) {
84	      out.push(cp);
85	    } else if (cp < 0x800) {
86	      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
87	    } else if (cp < 0x10000) {
88	      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
89	    } else {
90	      out.push(
91	        0xf0 | (cp >> 18),
92	        0x80 | ((cp >> 12) & 0x3f),
93	        0x80 | ((cp >> 6) & 0x3f),
94	        0x80 | (cp & 0x3f),
95	      );
96	    }
97	
98	    u += utf8Width(cp) === 4 ? 2 : 1;
99	    cpIndex += 1;
100	  }
101	
102	  return Uint8Array.from(out);
103	}
104	
105	/**
106	 * The continuation-byte range CPython accepts for a given lead byte. Encoding
107	 * these bounds (rather than a blanket 0x80..0xBF) is what rejects overlong
108	 * forms, UTF-8-encoded surrogates (0xED 0xA0..) and code points above U+10FFFF.
109	 */
110	function secondByteRange(lead) {
111	  if (lead === 0xe0) return [0xa0, 0xbf];
112	  if (lead === 0xed) return [0x80, 0x9f];
113	  if (lead === 0xf0) return [0x90, 0xbf];
114	  if (lead === 0xf4) return [0x80, 0x8f];
115	  return [0x80, 0xbf];
116	}
117	
118	/** Total UTF-8 sequence length for a lead byte, or 0 if it cannot start one. */
119	function sequenceLength(lead) {
120	  if (lead < 0x80) return 1;
121	  if (lead >= 0xc2 && lead <= 0xdf) return 2; // 0xc0/0xc1 are always overlong
122	  if (lead >= 0xe0 && lead <= 0xef) return 3;
123	  if (lead >= 0xf0 && lead <= 0xf4) return 4;
124	  return 0;
125	}
126	
127	/**
128	 * `bytes.decode('utf-8', errors='surrogateescape')`.
129	 *
130	 * On an invalid sequence CPython reports the *maximal subpart* (the lead byte
131	 * plus any continuation bytes that were still valid) and the surrogateescape
132	 * handler replaces each of those bytes individually with U+DC00+byte. So
133	 * b'\xff\xfe' becomes '\udcff\udcfe' — two code points, which is why the
134	 * executable reports "position 2-3" rather than "position 2".
135	 */
136	export function decodeSurrogateEscape(bytes) {
137	  const buf = bytes instanceof Uint8Array ? bytes : Uint8Array.from(bytes);
138	  let out = '';
139	  let i = 0;
140	
141	  const escapeRange = (from, to) => {
142	    for (let k = from; k < to; k += 1) out += String.fromCharCode(0xdc00 + buf[k]);
143	  };
144	
145	  while (i < buf.length) {
146	    const lead = buf[i];
147	
148	    if (lead < 0x80) {
149	      out += String.fromCharCode(lead);
150	      i += 1;
151	      continue;
152	    }
153	
154	    const len = sequenceLength(lead);
155	    if (len === 0) {
156	      escapeRange(i, i + 1);
157	      i += 1;
158	      continue;
159	    }
160	
161	    // Validate continuation bytes, tracking how many were acceptable so the
162	    // maximal subpart matches CPython's.
163	    let valid = 1;
164	    let ok = true;
165	    for (let k = 1; k < len; k += 1) {
166	      const pos = i + k;
167	      if (pos >= buf.length) {
168	        ok = false;
169	        break;
170	      }
171	      const b = buf[pos];
172	      const [lo, hi] = k === 1 ? secondByteRange(lead) : [0x80, 0xbf];
173	      if (b < lo || b > hi) {
174	        ok = false;
175	        break;
176	      }
177	      valid += 1;
178	    }
179	
180	    if (!ok) {
181	      escapeRange(i, i + valid);
182	      i += valid;
183	      continue;
184	    }
185	
186	    let cp;
187	    if (len === 2) {
188	      cp = ((lead & 0x1f) << 6) | (buf[i + 1] & 0x3f);
189	    } else if (len === 3) {
190	      cp = ((lead & 0x0f) << 12) | ((buf[i + 1] & 0x3f) << 6) | (buf[i + 2] & 0x3f);
191	    } else {
192	      cp =
193	        ((lead & 0x07) << 18) |
194	        ((buf[i + 1] & 0x3f) << 12) |
195	        ((buf[i + 2] & 0x3f) << 6) |
196	        (buf[i + 3] & 0x3f);
197	    }
198	    out += String.fromCodePoint(cp);
199	    i += len;
200	  }
201	
202	  return out;
203	}
204

1	/**
2	 * pyerrors.mjs — Python exception shapes reproduced in JavaScript.
3	 *
4	 * The migrated program has to distinguish three distinct exit behaviours that
5	 * CPython gives us for free:
6	 *
7	 *   * `SystemExit`          -> argparse's `--help` (code 0) and `error()` (code 2)
8	 *   * `UnicodeEncodeError`  -> `str.encode('utf-8')` over lone surrogates (code 1,
9	 *                              after a traceback on stderr)
10	 *   * `ValueError`/`TypeError` -> library misuse, surfaced with a traceback
11	 *
12	 * Each class carries the exact `__str__` rendering CPython produces, because the
13	 * text ends up on stderr verbatim.
14	 */
15	
16	/** Base class so callers can test `err instanceof PyError`. */
17	export class PyError extends Error {
18	  constructor(message) {
19	    super(message);
20	    this.name = 'PyError';
21	  }
22	
23	  /** Fully-qualified name used on the last line of a traceback. */
24	  get pyName() {
25	    return this.name;
26	  }
27	
28	  /** CPython's `str(exc)` — the text after the `ClassName: ` prefix. */
29	  toPyString() {
30	    return this.message;
31	  }
32	}
33	
34	/** `raise SystemExit(code)`, which is what `sys.exit()` and `parser.error()` do. */
35	export class SystemExit extends PyError {
36	  constructor(code = 0) {
37	    super(String(code));
38	    this.name = 'SystemExit';
39	    this.code = code;
40	  }
41	}
42	
43	export class PyValueError extends PyError {
44	  constructor(message) {
45	    super(message);
46	    this.name = 'ValueError';
47	  }
48	}
49	
50	export class PyTypeError extends PyError {
51	  constructor(message) {
52	    super(message);
53	    this.name = 'TypeError';
54	  }
55	}
56	
57	/**
58	 * Renders a single code point the way CPython's `unicode_repr`-style helper does
59	 * inside `UnicodeEncodeError.__str__`: `\xXX`, `\uXXXX` or `\UXXXXXXXX`,
60	 * always lowercase hex.
61	 */
62	function escapeCodePoint(cp) {
63	  if (cp < 0x100) return '\\x' + cp.toString(16).padStart(2, '0');
64	  if (cp < 0x10000) return '\\u' + cp.toString(16).padStart(4, '0');
65	  return '\\U' + cp.toString(16).padStart(8, '0');
66	}
67	
68	/**
69	 * `UnicodeEncodeError(encoding, object, start, end, reason)`.
70	 *
71	 * CPython formats the message two different ways depending on how many code
72	 * points are unencodable:
